function Neverlose_Main:PlaySound(SoundID)
    local sound = Instance.new("Sound")
    sound.SoundId = SoundID
    sound.Looped = false
    sound.Parent = workspace
    sound.Volume = 0.15
    sound:Play()
    game:GetService("Debris"):AddItem(sound, 2)
end

