        ToggledText.TextColor3 = Color3.fromRGB(255, 255, 255)
        ToggledText.TextSize = 14.000
        ToggledText.RichText = true

        if state then
            ToggledText.Text = text.. " | <font color='rgb(50,255,50)'>ON</font>"
