                    ButtonTitle.TextYAlignment = Enum.TextYAlignment.Center

                    spawn(function()
                        while false do -- R227: no per-frame theme polling
                            pcall(function()
                                ChangeTypeText(ButtonTitle)
                                ButtonStroke.Color = Neverlose_Main.Theme.Custom.Element
