        for _,kind in ipairs({'Toggle','Slider','Dropdown','Input','Colorpicker'}) do
            tab['Add'..kind]=function(_,id,c)return addOption(kind,id,c)end
        end
        function tab:AddButton(info)
            info=info or {};self.OptionCount=self.OptionCount+1
